function maximalSquare(matrix: string[][]): number {
  const m = matrix.length;
  const n = matrix[0].length;

  // dp[j + 1] — сторона наибольшего квадрата из единиц с правым нижним углом
  // в клетке (i, j). Храним одну строку; dp[0] — фиктивный столбец нулей
  const dp: number[] = new Array(n + 1).fill(0);
  let maxSide = 0;

  for (let i = 0; i < m; i++) {
    // prev — значение dp «по диагонали» (строка i - 1, столбец j - 1)
    let prev = 0;
    for (let j = 0; j < n; j++) {
      // Сохраняем «верхнее» значение: на следующем шаге оно станет диагональю
      const top = dp[j + 1];
      if (matrix[i][j] === '1') {
        // Квадрат ограничен самым маленьким из трёх соседних квадратов:
        // сверху (top), слева (dp[j]) и по диагонали (prev)
        dp[j + 1] = Math.min(top, dp[j], prev) + 1;
        maxSide = Math.max(maxSide, dp[j + 1]);
      } else {
        // Ноль не может быть углом квадрата из единиц
        dp[j + 1] = 0;
      }
      prev = top;
    }
  }

  // Возвращаем площадь, а не сторону
  return maxSide * maxSide;
}

// Время: O(m · n)
// Память: O(n) — одна строка dp
